{
  "bbb_prediction": "pass",
  "claims": [
    {
      "card_ids": ["C03"],
      "claim": "The highest-transfer analogue, hydroxysafflor yellow A, a highly polar multi-glycoside, reached 1026 ng/g in rat brain after systemic administration, demonstrating that large polar glycosides can achieve measurable CNS exposure.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C07"],
      "claim": "A triterpenoid saponin glycoside (A-VI) penetrated the BBB in healthy rats with a brain concentration of 248.7 ng/g, supporting meaningful CNS access for glycoside-type natural products.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C11"],
      "claim": "Ginsenoside Rh3, a glycosylated triterpenoid, accumulated to 520 ng/g in rat hippocampus after oral administration, showing that glycosides can cross the BBB after systemic dosing.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C05"],
      "claim": "Hesperidin, a flavonoid glycoside, was detected in mouse brain after oral administration and distributed to brain tissues, supporting CNS access for glycosylated polyphenolic compounds.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C10"],
      "claim": "A glucose-conjugated prodrug showed transporter-mediated brain uptake in situ, providing a plausible mechanism by which the glucose moiety of the query could facilitate BBB transport.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "Pass: multiple high-transfer glycoside and saponin analogues show measurable brain concentrations after systemic administration, and the query's glycoside structure is consistent with transporter-mediated or otherwise meaningful CNS access despite its polarity.",
  "evidence_gaps": [
    "No direct brain/plasma ratio or CSF measurement is available for the exact query molecule.",
    "Brain concentrations in the supporting analogues are low relative to plasma and may involve transporter-mediated uptake or partial BBB disruption.",
    "Efflux liability and unbound brain exposure for the query are not directly quantified."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

